-- Checkpoint 247 / V-04: append-only Fehler-/Beinahefehlerakte mit unterdrückter Aggregation.
-- Lokaler additiver Entwurf; bewusst nicht gegen eine produktive Datenbank ausgeführt.
CREATE TABLE IF NOT EXISTS public.qm_safety_incidents(
 id uuid PRIMARY KEY,client_request_id uuid NOT NULL,tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
 classification text NOT NULL CHECK(classification IN('error','near_miss')),category text NOT NULL CHECK(category IN('medication','fall','documentation','communication','hygiene','care_process','other')),care_setting text NOT NULL CHECK(care_setting IN('home_visit','office','transport','remote','other')),
 client_id uuid REFERENCES public.clients(id) ON DELETE RESTRICT,source_emergency_id uuid,description text NOT NULL CHECK(length(btrim(description))>=5),impact_code text NOT NULL CHECK(impact_code IN('not_reached','no_observed_harm','temporary_harm','permanent_harm','death','unknown')),impact_summary text NOT NULL CHECK(length(btrim(impact_summary))>=3),
 occurred_at timestamptz NOT NULL,observed_at timestamptz NOT NULL CHECK(observed_at>=occurred_at),recorded_at timestamptz NOT NULL CHECK(recorded_at>=observed_at),reporter_mode text NOT NULL CHECK(reporter_mode IN('named','anonymous')),reporter_id uuid,reporter_name text,recorded_by uuid NOT NULL REFERENCES auth.users(id),recorded_by_name text NOT NULL CHECK(btrim(recorded_by_name)<>''),request_fingerprint text NOT NULL CHECK(request_fingerprint~'^[0-9a-f]{32}$'),
 CHECK((classification='near_miss' AND impact_code='not_reached')OR(classification='error' AND impact_code<>'not_reached')),CHECK((reporter_mode='anonymous' AND reporter_id IS NULL AND reporter_name IS NULL)OR(reporter_mode='named' AND reporter_id IS NOT NULL AND btrim(reporter_name)<>'')),UNIQUE(tenant_id,client_request_id),UNIQUE(tenant_id,id)
);
CREATE TABLE IF NOT EXISTS public.qm_safety_incident_events(
 id uuid PRIMARY KEY,client_request_id uuid NOT NULL,tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,incident_id uuid NOT NULL REFERENCES public.qm_safety_incidents(id) ON DELETE RESTRICT,sequence_no integer NOT NULL CHECK(sequence_no>=1),
 event_kind text NOT NULL CHECK(event_kind IN('immediate_action','causal_analysis','corrective_action','effectiveness_review','closure','reopened')),occurred_at timestamptz NOT NULL,recorded_at timestamptz NOT NULL CHECK(recorded_at>=occurred_at),actor_id uuid NOT NULL REFERENCES auth.users(id),actor_name text NOT NULL CHECK(btrim(actor_name)<>''),summary text NOT NULL CHECK(length(btrim(summary))>=5),
 assigned_owner_id uuid,assigned_owner_name text,due_at timestamptz,review_outcome text CHECK(review_outcome IN('effective','partially_effective','not_effective')),closure_outcome text CHECK(closure_outcome IN('risk_controlled','follow_up_required','closed_without_harm_inference')),result_sha256 text CHECK(result_sha256~'^[0-9a-f]{64}$'),references_event_ids uuid[] NOT NULL DEFAULT '{}',request_fingerprint text NOT NULL CHECK(request_fingerprint~'^[0-9a-f]{32}$'),
 CHECK((event_kind='corrective_action')=(assigned_owner_id IS NOT NULL AND btrim(assigned_owner_name)<>'' AND due_at IS NOT NULL)),CHECK((event_kind='effectiveness_review')=(review_outcome IS NOT NULL AND result_sha256 IS NOT NULL)),CHECK((event_kind='closure')=(closure_outcome IS NOT NULL AND result_sha256 IS NOT NULL)),UNIQUE(tenant_id,client_request_id),UNIQUE(incident_id,sequence_no),UNIQUE(incident_id,id)
);
CREATE TABLE IF NOT EXISTS public.qm_safety_incident_evidence(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,incident_id uuid NOT NULL REFERENCES public.qm_safety_incidents(id) ON DELETE RESTRICT,event_id uuid NOT NULL REFERENCES public.qm_safety_incident_events(id) ON DELETE RESTRICT,position_no integer NOT NULL CHECK(position_no>=1),source_type text NOT NULL CHECK(source_type IN('care_record','tour_stop_emergency','qm_document_version','incident_report','other')),source_entity_id uuid NOT NULL,source_version_id uuid,record_locator text NOT NULL CHECK(btrim(record_locator)<>''),source_sha256 text NOT NULL CHECK(source_sha256~'^[0-9a-f]{64}$'),UNIQUE(event_id,position_no),UNIQUE(event_id,id)
);
ALTER TABLE public.qm_safety_incidents ENABLE ROW LEVEL SECURITY;ALTER TABLE public.qm_safety_incident_events ENABLE ROW LEVEL SECURITY;ALTER TABLE public.qm_safety_incident_evidence ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.qm_safety_incidents,public.qm_safety_incident_events,public.qm_safety_incident_evidence FROM PUBLIC,anon,authenticated;GRANT SELECT ON public.qm_safety_incidents,public.qm_safety_incident_events,public.qm_safety_incident_evidence TO authenticated;
DROP POLICY IF EXISTS qm_safety_incidents_read ON public.qm_safety_incidents;CREATE POLICY qm_safety_incidents_read ON public.qm_safety_incidents FOR SELECT TO authenticated USING(tenant_id=public.current_tenant_id() AND public.has_permission('qm.view'));
DROP POLICY IF EXISTS qm_safety_incident_events_read ON public.qm_safety_incident_events;CREATE POLICY qm_safety_incident_events_read ON public.qm_safety_incident_events FOR SELECT TO authenticated USING(tenant_id=public.current_tenant_id() AND public.has_permission('qm.view'));
DROP POLICY IF EXISTS qm_safety_incident_evidence_read ON public.qm_safety_incident_evidence;CREATE POLICY qm_safety_incident_evidence_read ON public.qm_safety_incident_evidence FOR SELECT TO authenticated USING(tenant_id=public.current_tenant_id() AND public.has_permission('qm.view'));
CREATE OR REPLACE FUNCTION care_private.protect_qm_safety_history()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN RAISE EXCEPTION 'Fehlerakte bleibt append-only.' USING ERRCODE='42501';END$$;
DROP TRIGGER IF EXISTS protect_qm_safety_incidents ON public.qm_safety_incidents;CREATE TRIGGER protect_qm_safety_incidents BEFORE UPDATE OR DELETE ON public.qm_safety_incidents FOR EACH ROW EXECUTE FUNCTION care_private.protect_qm_safety_history();
DROP TRIGGER IF EXISTS protect_qm_safety_incident_events ON public.qm_safety_incident_events;CREATE TRIGGER protect_qm_safety_incident_events BEFORE UPDATE OR DELETE ON public.qm_safety_incident_events FOR EACH ROW EXECUTE FUNCTION care_private.protect_qm_safety_history();
DROP TRIGGER IF EXISTS protect_qm_safety_incident_evidence ON public.qm_safety_incident_evidence;CREATE TRIGGER protect_qm_safety_incident_evidence BEFORE UPDATE OR DELETE ON public.qm_safety_incident_evidence FOR EACH ROW EXECUTE FUNCTION care_private.protect_qm_safety_history();

CREATE OR REPLACE FUNCTION public.read_anonymous_qm_safety_aggregate(p_tenant_id uuid,p_minimum_cohort integer DEFAULT 5)
RETURNS TABLE(quarter text,classification text,category text,incident_count bigint,suppressed boolean)
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path='' AS $$
DECLARE t uuid:=public.current_tenant_id();
BEGIN
 IF auth.uid() IS NULL OR t IS NULL OR p_tenant_id IS DISTINCT FROM t OR NOT public.has_permission('qm.view') THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501';END IF;
 IF p_minimum_cohort<5 THEN RAISE EXCEPTION 'Kohortenschwelle muss mindestens fünf sein.' USING ERRCODE='23514';END IF;
 RETURN QUERY SELECT (extract(year from i.occurred_at)::integer||'-Q'||extract(quarter from i.occurred_at)::integer)::text,i.classification,i.category,count(*),false FROM public.qm_safety_incidents i WHERE i.tenant_id=t GROUP BY extract(year from i.occurred_at),extract(quarter from i.occurred_at),i.classification,i.category HAVING count(*)>=p_minimum_cohort ORDER BY 1,2,3;
END$$;
REVOKE ALL ON FUNCTION public.read_anonymous_qm_safety_aggregate(uuid,integer)FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.read_anonymous_qm_safety_aggregate(uuid,integer)TO authenticated;

CREATE OR REPLACE FUNCTION public.record_qm_safety_incident(p_payload jsonb,p_client_request_id uuid)RETURNS public.qm_safety_incidents
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE t uuid:=public.current_tenant_id();actor uuid:=auth.uid();actor_name text:=public.clinical_actor_name();actual_time timestamptz:=clock_timestamp();result public.qm_safety_incidents;prior public.qm_safety_incidents;root_fp text;event_item record;evidence_item record;event_fp text;seq integer;last_kind text;last_occurred_at timestamptz;last_recorded_at timestamptz;last_reopen integer:=0;cause_count integer;action_count integer;review_count integer;refs uuid[];client uuid;emergency uuid;
BEGIN
 IF t IS NULL OR actor IS NULL OR NOT public.has_permission('qm.create_audit') THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501';END IF;
 IF p_payload IS NULL OR p_client_request_id IS NULL OR p_payload->>'clientRequestId' IS DISTINCT FROM p_client_request_id::text OR COALESCE(p_payload->>'incidentId','')='' OR jsonb_typeof(p_payload->'events')<>'array' OR COALESCE(p_payload->>'occurredAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$' OR COALESCE(p_payload->>'observedAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$' OR COALESCE(p_payload->>'recordedAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$' THEN RAISE EXCEPTION 'Fehlerereignis ist unvollständig.' USING ERRCODE='23514';END IF;
 client:=NULLIF(p_payload->>'clientId','')::uuid;emergency:=NULLIF(p_payload->>'sourceEmergencyId','')::uuid;
 IF(p_payload->>'tenantId')::uuid IS DISTINCT FROM t OR COALESCE(p_payload->>'classification','')NOT IN('error','near_miss')OR COALESCE(p_payload->>'category','')NOT IN('medication','fall','documentation','communication','hygiene','care_process','other')OR(client IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clients WHERE tenant_id=t AND id=client))THEN RAISE EXCEPTION 'Mandant, Klassifikation, Kategorie oder Pflegefall ist widersprüchlich.' USING ERRCODE='23514';END IF;
 IF emergency IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.care_tour_stop_emergencies WHERE tenant_id=t AND id=emergency AND client_id IS NOT DISTINCT FROM client)THEN RAISE EXCEPTION 'Originalnotfall fehlt oder gehört nicht zum Pflegefall.' USING ERRCODE='23503';END IF;
 IF(p_payload->>'classification'='near_miss' AND p_payload->>'impactCode'<>'not_reached')OR(p_payload->>'classification'='error' AND p_payload->>'impactCode'='not_reached')OR(p_payload->>'reporterMode'='anonymous' AND(NULLIF(p_payload->>'reporterId','')IS NOT NULL OR NULLIF(btrim(COALESCE(p_payload->>'reporterName','')),'')IS NOT NULL))THEN RAISE EXCEPTION 'Klassifikation, Auswirkung oder Anonymität ist widersprüchlich.' USING ERRCODE='23514';END IF;
 root_fp:=md5(jsonb_build_object('root',p_payload-'events')::text);PERFORM pg_advisory_xact_lock(hashtext(t::text),hashtext(p_payload->>'incidentId'));
 SELECT*INTO prior FROM public.qm_safety_incidents WHERE tenant_id=t AND id=(p_payload->>'incidentId')::uuid;
 IF FOUND THEN IF prior.request_fingerprint IS DISTINCT FROM root_fp OR prior.client_request_id IS DISTINCT FROM p_client_request_id THEN RAISE EXCEPTION 'Ereignisidentität wurde anders verwendet.' USING ERRCODE='40001';END IF;result:=prior;
 ELSE
  IF(p_payload->>'recordedBy')::uuid IS DISTINCT FROM actor OR btrim(p_payload->>'recordedByName')IS DISTINCT FROM btrim(actor_name)OR(p_payload->>'occurredAt')::timestamptz>(p_payload->>'observedAt')::timestamptz OR(p_payload->>'observedAt')::timestamptz>(p_payload->>'recordedAt')::timestamptz OR(p_payload->>'recordedAt')::timestamptz>actual_time THEN RAISE EXCEPTION 'Zeitfolge oder Erfassungsidentität ist widersprüchlich.' USING ERRCODE='23514';END IF;
  INSERT INTO public.qm_safety_incidents(id,client_request_id,tenant_id,classification,category,care_setting,client_id,source_emergency_id,description,impact_code,impact_summary,occurred_at,observed_at,recorded_at,reporter_mode,reporter_id,reporter_name,recorded_by,recorded_by_name,request_fingerprint)VALUES((p_payload->>'incidentId')::uuid,p_client_request_id,t,p_payload->>'classification',p_payload->>'category',p_payload->>'careSetting',client,emergency,btrim(p_payload->>'description'),p_payload->>'impactCode',btrim(p_payload->>'impactSummary'),(p_payload->>'occurredAt')::timestamptz,(p_payload->>'observedAt')::timestamptz,(p_payload->>'recordedAt')::timestamptz,p_payload->>'reporterMode',NULLIF(p_payload->>'reporterId','')::uuid,NULLIF(btrim(COALESCE(p_payload->>'reporterName','')),''),actor,actor_name,root_fp)RETURNING*INTO result;
 END IF;
 SELECT COALESCE(max(sequence_no),0),(array_agg(occurred_at ORDER BY sequence_no DESC))[1],(array_agg(recorded_at ORDER BY sequence_no DESC))[1],(array_agg(event_kind ORDER BY sequence_no DESC))[1] INTO seq,last_occurred_at,last_recorded_at,last_kind FROM public.qm_safety_incident_events WHERE incident_id=result.id;SELECT COALESCE(max(sequence_no),0)INTO last_reopen FROM public.qm_safety_incident_events WHERE incident_id=result.id AND event_kind='reopened';
 FOR event_item IN SELECT value,ordinality FROM jsonb_array_elements(p_payload->'events')WITH ORDINALITY LOOP
  event_fp:=md5(event_item.value::text);IF EXISTS(SELECT 1 FROM public.qm_safety_incident_events WHERE tenant_id=t AND client_request_id=(event_item.value->>'clientRequestId')::uuid AND request_fingerprint=event_fp)THEN CONTINUE;END IF;
  IF EXISTS(SELECT 1 FROM public.qm_safety_incident_events WHERE tenant_id=t AND client_request_id=(event_item.value->>'clientRequestId')::uuid)OR COALESCE(event_item.value->>'occurredAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$'OR COALESCE(event_item.value->>'recordedAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$'OR(event_item.value->>'occurredAt')::timestamptz>(event_item.value->>'recordedAt')::timestamptz OR(event_item.value->>'recordedAt')::timestamptz>actual_time OR(last_occurred_at IS NOT NULL AND(event_item.value->>'occurredAt')::timestamptz<last_occurred_at)OR(last_recorded_at IS NOT NULL AND(event_item.value->>'recordedAt')::timestamptz<last_recorded_at)OR jsonb_typeof(event_item.value->'evidence')<>'array'OR jsonb_typeof(event_item.value->'referencesEventIds')<>'array'THEN RAISE EXCEPTION 'Verlauf ist doppelt, unvollständig oder zeitlich widersprüchlich.' USING ERRCODE='40001';END IF;
  refs:=ARRAY(SELECT jsonb_array_elements_text(event_item.value->'referencesEventIds')::uuid);cause_count:=(SELECT count(*)FROM public.qm_safety_incident_events WHERE incident_id=result.id AND sequence_no>last_reopen AND event_kind='causal_analysis');action_count:=(SELECT count(*)FROM public.qm_safety_incident_events WHERE incident_id=result.id AND sequence_no>last_reopen AND event_kind='corrective_action');review_count:=(SELECT count(*)FROM public.qm_safety_incident_events WHERE incident_id=result.id AND sequence_no>last_reopen AND event_kind='effectiveness_review');
  IF last_kind='closure'AND event_item.value->>'kind'<>'reopened'THEN RAISE EXCEPTION 'Geschlossenes Ereignis benötigt Wiederaufnahme.' USING ERRCODE='23514';END IF;
  IF event_item.value->>'kind'IN('immediate_action','causal_analysis','corrective_action','effectiveness_review','closure')AND jsonb_array_length(event_item.value->'evidence')<1 THEN RAISE EXCEPTION 'Bearbeitung benötigt einen konkreten Beleg.' USING ERRCODE='23514';END IF;
  IF event_item.value->>'kind'='corrective_action'AND(btrim(COALESCE(event_item.value->>'assignedOwnerName',''))=''OR(event_item.value->>'dueAt')::timestamptz<=(event_item.value->>'occurredAt')::timestamptz OR NOT EXISTS(SELECT 1 FROM public.qm_safety_incident_events WHERE incident_id=result.id AND sequence_no>last_reopen AND event_kind='causal_analysis'AND id=ANY(refs)))THEN RAISE EXCEPTION 'Maßnahme benötigt Ursache, Verantwortung und Frist.' USING ERRCODE='23514';END IF;
  IF event_item.value->>'kind'='effectiveness_review'AND(COALESCE(event_item.value->>'reviewOutcome','')NOT IN('effective','partially_effective','not_effective')OR COALESCE(event_item.value->>'resultSha256','')!~'^[0-9a-f]{64}$'OR NOT EXISTS(SELECT 1 FROM public.qm_safety_incident_events WHERE incident_id=result.id AND sequence_no>last_reopen AND event_kind='corrective_action'AND id=ANY(refs)))THEN RAISE EXCEPTION 'Wirksamkeitsprüfung benötigt Maßnahme, Ergebnis und Beleg.' USING ERRCODE='23514';END IF;
  IF event_item.value->>'kind'='closure'AND(NOT public.has_permission('qm.close_audit')OR cause_count<1 OR action_count<1 OR review_count<1 OR COALESCE(event_item.value->>'closureOutcome','')NOT IN('risk_controlled','follow_up_required','closed_without_harm_inference')OR COALESCE(event_item.value->>'resultSha256','')!~'^[0-9a-f]{64}$'OR NOT EXISTS(SELECT 1 FROM public.qm_safety_incident_events WHERE incident_id=result.id AND sequence_no>last_reopen AND event_kind='causal_analysis'AND id=ANY(refs))OR NOT EXISTS(SELECT 1 FROM public.qm_safety_incident_events WHERE incident_id=result.id AND sequence_no>last_reopen AND event_kind='corrective_action'AND id=ANY(refs))OR NOT EXISTS(SELECT 1 FROM public.qm_safety_incident_events WHERE incident_id=result.id AND sequence_no>last_reopen AND event_kind='effectiveness_review'AND id=ANY(refs)))THEN RAISE EXCEPTION 'Abschluss benötigt Ursache, Maßnahme, Wirksamkeitsprüfung und Schließrecht.' USING ERRCODE='42501';END IF;
  IF event_item.value->>'kind'='reopened'AND(last_kind<>'closure'OR jsonb_array_length(event_item.value->'evidence')<>0)THEN RAISE EXCEPTION 'Nur ein abgeschlossenes Ereignis kann ohne erfundenen Beleg wiederaufgenommen werden.' USING ERRCODE='23514';END IF;
  seq:=seq+1;INSERT INTO public.qm_safety_incident_events(id,client_request_id,tenant_id,incident_id,sequence_no,event_kind,occurred_at,recorded_at,actor_id,actor_name,summary,assigned_owner_id,assigned_owner_name,due_at,review_outcome,closure_outcome,result_sha256,references_event_ids,request_fingerprint)VALUES((event_item.value->>'eventId')::uuid,(event_item.value->>'clientRequestId')::uuid,t,result.id,seq,event_item.value->>'kind',(event_item.value->>'occurredAt')::timestamptz,(event_item.value->>'recordedAt')::timestamptz,actor,actor_name,btrim(event_item.value->>'summary'),NULLIF(event_item.value->>'assignedOwnerId','')::uuid,NULLIF(btrim(COALESCE(event_item.value->>'assignedOwnerName','')),''),NULLIF(event_item.value->>'dueAt','')::timestamptz,NULLIF(event_item.value->>'reviewOutcome',''),NULLIF(event_item.value->>'closureOutcome',''),NULLIF(event_item.value->>'resultSha256',''),refs,event_fp);
  FOR evidence_item IN SELECT value,ordinality FROM jsonb_array_elements(event_item.value->'evidence')WITH ORDINALITY LOOP IF btrim(COALESCE(evidence_item.value->>'recordLocator',''))=''OR COALESCE(evidence_item.value->>'sourceSha256','')!~'^[0-9a-f]{64}$'THEN RAISE EXCEPTION 'Beleg ist unvollständig.' USING ERRCODE='23514';END IF;INSERT INTO public.qm_safety_incident_evidence(id,tenant_id,incident_id,event_id,position_no,source_type,source_entity_id,source_version_id,record_locator,source_sha256)VALUES((evidence_item.value->>'evidenceId')::uuid,t,result.id,(event_item.value->>'eventId')::uuid,evidence_item.ordinality,evidence_item.value->>'sourceType',(evidence_item.value->>'sourceEntityId')::uuid,NULLIF(evidence_item.value->>'sourceVersionId','')::uuid,btrim(evidence_item.value->>'recordLocator'),evidence_item.value->>'sourceSha256');END LOOP;
  last_kind:=event_item.value->>'kind';last_occurred_at:=(event_item.value->>'occurredAt')::timestamptz;last_recorded_at:=(event_item.value->>'recordedAt')::timestamptz;IF last_kind='reopened'THEN last_reopen:=seq;END IF;
 END LOOP;
 INSERT INTO public.care_audit_events(tenant_id,entity_type,entity_id,action,summary,after_data,actor_id,actor_name)VALUES(t,'qm_safety_incident',result.id,'safety_history_recorded','Fehlerakte append-only fortgeschrieben; Einzelfall und anonymisierte Auswertung getrennt.',to_jsonb(result)-'reporter_id'-'reporter_name',actor,actor_name);RETURN result;
END$$;
REVOKE ALL ON FUNCTION public.record_qm_safety_incident(jsonb,uuid)FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.record_qm_safety_incident(jsonb,uuid)TO authenticated;
